import { createStorage, StorageEnum } from '../base/index.js';
const storage = createStorage('chat-alignment-storage-key', {
    alignment: 'left',
}, {
    storageEnum: StorageEnum.Local,
    liveUpdate: true,
});
export const exampleChatAlignmentStorage = {
    ...storage,
    setAlignment: async (alignment) => {
        await storage.set({ alignment });
    },
    getAlignment: async () => {
        const state = await storage.get();
        return state.alignment;
    },
};
